import { styled } from '@hexa-ui/theme';

export const StyledSustainableGrowthOverviewCardContent = styled('div', {
  width: '198px',
  minHeight: '468px',

  '@media (min-width: 1440px)': {
    width: '228px',
  },

  '@media (min-width: 1920px)': {
    width: '264px',
  },

  '.bigNumberContainer': {
    height: 'auto',
  },

  variants: {
    isExportPage: {
      true: {
        width: '312px',
        minHeight: '568px',

        '@media (min-width: 1440px)': {
          width: '312px',
        },

        '@media (min-width: 1920px)': {
          width: '312px',
        },
      },
    },
  },
});

export const StyledNoticeMessageContainer = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  gap: '2rem',
  padding: '16px',
});

export const StyledChartContainer = styled('div', {
  height: `300px`,
  maxWidth: '228px',
  display: 'flex',
  marginBottom: `8px`,
  borderTop: '1px solid #14141414',

  '@media (min-width: 1440px)': {
    maxWidth: '228px',
  },

  '@media (min-width: 1920px)': {
    maxWidth: '264px',
  },

  variants: {
    hasNoticeMessage: {
      true: {
        height: '359px',
        justifyContent: 'center',
        alignItems: 'center',
        borderTop: 'none',
      },
    },

    isExportPage: {
      true: {
        height: '380px',
        maxWidth: '312px',

        '@media (min-width: 1440px)': {
          maxWidth: '312px',
        },

        '@media (min-width: 1920px)': {
          maxWidth: '312px',
        },
      },
    },
  },
});
